SELECT pg_typeof(cohort_quarter) FROM (
    SELECT EXTRACT(YEAR FROM (scoredate::date - INTERVAL '1 year' * tenureyrs)) AS cohort_quarter 
    FROM core_record LIMIT 1
) sub;

SELECT 
    COUNT(DISTINCT DATE_TRUNC('quarter', (scoredate::date - INTERVAL '1 year' * tenureyrs)::timestamp)) AS distinct_quarters
FROM core_record;

SELECT 
    EXTRACT(YEAR FROM (scoredate::date - INTERVAL '1 year' * tenureyrs)) || '-Q' || EXTRACT(QUARTER FROM (scoredate::date - INTERVAL '1 year' * tenureyrs)) AS cohort_quarter
FROM core_record LIMIT 5;

SELECT DISTINCT 
    DATE_TRUNC('quarter', (scoredate::date - INTERVAL '1 year' * tenureyrs)::timestamp)::date AS cohort_quarter
FROM core_record ORDER BY 1 LIMIT 5;

-- Check if credit_accounts_and_history directly links to core_record somehow
SELECT COUNT(*) FROM credit_accounts_and_history ca
JOIN core_record cr ON ca.histcompref = cr.coreregistry;

-- Check if all keys are the same set
SELECT COUNT(*) FROM (
    SELECT histcompref FROM credit_accounts_and_history
    EXCEPT
    SELECT coreregistry FROM core_record
) diff;

SELECT COUNT(*) FROM (
    SELECT bankexpref FROM bank_and_transactions
    EXCEPT
    SELECT coreregistry FROM core_record
) diff;

-- Check if histcompref matches bankexpref directly
SELECT COUNT(*) FROM credit_accounts_and_history ca
JOIN bank_and_transactions bt ON ca.histcompref = bt.bankexpref;
